def name_operands(region,function_address,operation):
    if region=='Action' and function_address in FUNCTIONS:
        operation=operation.replace('LD HL, #CF07','LD HL, @ActionClipCasesState.SeenFlags')
        for bit,name in enumerate(('BottomRight','BottomLeft','TopRight','TopLeft')):
            for instruction in ('BIT','SET'):
                operation=operation.replace(instruction+' '+str(bit)+', (HL)',instruction+' @ActionClipSeenBits.'+name+', (HL)')
